import sys, re
src, out = sys.argv[1:3]
t = open(src, encoding="utf-8").read()
def rep(prefix, new):
    """Replace the whole <p>…</p> (or <li>…</li> head) whose text starts with `prefix`."""
    global t
    i = t.find(prefix); assert i >= 0, prefix[:50]; assert t.find(prefix, i + 1) < 0, "not unique: " + prefix[:50]
    s = t.rfind("<p", 0, i); e = t.find("</p>", i) + 4
    assert s >= 0 and t.find("</p>", s) == e - 4, prefix[:50]
    t = t[:s] + new + t[e:]
def drop(prefix): rep(prefix, "")
def repli(prefix, new):
    """The same for a list item that holds no nested list."""
    global t
    i = t.find(prefix); assert i >= 0, prefix[:50]; assert t.find(prefix, i + 1) < 0, "not unique: " + prefix[:50]
    s = t.rfind("<li>", 0, i); e = t.find("</li>", i) + 5
    assert "<li>" not in t[s + 4:e - 5], "nested: " + prefix[:50]
    t = t[:s] + new + t[e:]

